    feedbackTip = {"Open the feedback link and QR code.", "Öffnet den Feedback-Link und den QR-Code.", "Abre el enlace y el código QR de comentarios.", "Ouvre le lien et le code QR de feedback.", "Geri bildirim bağlantısını ve QR kodunu açar.", "打开反馈链接和二维码。"},
    showMenuTip = {"Show the Next quest list on screen.", "Zeigt die Questliste von Next an.", "Muestra la lista de misiones de Next.", "Affiche la liste des quêtes de Next.", "Next görev listesini gösterir.", "在屏幕上显示 Next 的任务列表。"},
    transparentBackgroundTip = {"Hide the quest window’s background and controls while keeping the quest list visible.", "Blendet Hintergrund und Bedienelemente des Questfensters aus. Die Questliste bleibt sichtbar.", "Oculta el fondo y los controles de la ventana. La lista de misiones sigue visible.", "Masque le fond et les commandes de la fenêtre. La liste des quêtes reste visible.", "Görev penceresinin arka planını ve kontrollerini gizler. Görev listesi görünür kalır.", "隐藏任务窗口的背景和控件，保留任务列表。"},
    windowSizeTip = {"Adjust the size of the quest window and its contents.", "Skaliert das Questfenster und seinen Inhalt.", "Ajusta la escala de la ventana de misiones y su contenido.", "Ajuste la taille de la fenêtre des quêtes et de son contenu.", "Görev penceresinin ve içeriğinin ölçeğini ayarlar.", "调整任务窗口及其内容的缩放。"},
    preferredRaidIconTip = {"Choose the icon used by buttons set to Raid marker. Group permissions still apply.", "Wählt das Zeichen für Buttons im Modus Schlachtzugszeichen. Gruppenrechte gelten weiterhin.", "Elige el icono para los botones configurados con Marca de banda. Se aplican los permisos del grupo.", "Choisit l’icône des boutons réglés sur Marqueur de raid. Les droits du groupe s’appliquent.", "Baskın işareti kullanan düğmelerin simgesini seçer. Grup izinleri geçerlidir.", "为设为团队标记的按钮选择图标。仍需遵守队伍权限。"},
    followTheArrowIntegrationTip = {"Add the current Follow The Arrow targets to the master button. Enable FTA Target in Follow The Arrow. The current Retail version provides no FTA Target macro.", "Fügt aktuelle Ziele aus Follow The Arrow zur Suche des Masterbuttons hinzu. Aktiviere das FTA-Target-Makro in Follow The Arrow. Die aktuelle Retail-Ausgabe stellt dieses Makro nicht bereit.", "Añade al botón principal los objetivos actuales de Follow The Arrow. Activa la macro FTA Target en Follow The Arrow. La versión Retail actual no incluye esa macro.", "Ajoute les cibles actuelles de Follow The Arrow au bouton principal. Activez la macro FTA Target dans Follow The Arrow. La version Retail actuelle ne fournit pas cette macro.", "Follow The Arrow’un güncel hedeflerini ana düğmeye ekler. Follow The Arrow’da FTA Target makrosunu aç. Güncel Retail sürümü bu makroyu sağlamıyor.", "将 Follow The Arrow 的当前目标加入主按钮。请在 Follow The Arrow 中启用 FTA Target 宏。当前正式服版本不提供此宏。"},
    polestarIntegrationTip = { "Add open goals from the current Polestar guide step to the master button. Polestar targets work without QuestieDB and can be used alongside RestedXP.", "Fügt offene Ziele des aktuellen Polestar-Schritts zur Suche des Masterbuttons hinzu. Polestar-Ziele funktionieren ohne QuestieDB und können zusammen mit RestedXP verwendet werden.", "Añade al botón maestro los objetivos pendientes del paso actual de Polestar. Los objetivos de Polestar funcionan sin QuestieDB y pueden usarse junto con RestedXP.", "Ajoute les objectifs ouverts de l’étape Polestar en cours au bouton principal. Les cibles de Polestar fonctionnent sans QuestieDB et peuvent être utilisées avec RestedXP.", "Geçerli Polestar adımının açık hedeflerini ana düğmeye ekler. Polestar hedefleri QuestieDB olmadan çalışır ve RestedXP ile birlikte kullanılabilir.", "将当前 Polestar 步骤的未完成目标加入主按钮的搜索。Polestar 目标无需 QuestieDB，也可以与 RestedXP 同时使用。" },
    restedXPSourceTip = { "Searches only RestedXP’s active guide targets. Nearby targets with known coordinates come first.", "Sucht nur die aktiven Guideziele von RestedXP. Ziele mit nahen bekannten Koordinaten kommen zuerst.", "Busca solo los objetivos activos de RestedXP. Prioriza los objetivos cercanos con coordenadas conocidas.", "Recherche uniquement les objectifs actifs de RestedXP. Les cibles proches aux coordonnées connues passent en premier.", "Yalnızca RestedXP’nin etkin rehber hedeflerini arar. Koordinatları bilinen yakın hedeflere öncelik verir.", "仅搜索 RestedXP 的当前指南目标。优先搜索坐标已知的附近目标。" },
    restedXPIntegrationTip = { "Show the blue button for RestedXP guide targets and include those targets in the master button’s search.", "Zeigt den blauen Button für RestedXP-Guideziele und fügt dieselben Ziele zur Suche des Masterbuttons hinzu.", "Muestra el botón azul para los objetivos de RestedXP y los añade a la búsqueda del botón maestro.", "Affiche le bouton bleu des cibles RestedXP et les ajoute à la recherche du bouton principal.", "RestedXP hedefleri için mavi düğmeyi gösterir ve bu hedefleri ana düğmenin aramasına ekler.", "显示用于 RestedXP 指南目标的蓝色按钮，并将这些目标加入主按钮的搜索。" },
    itemTreeIntegrationTip = {"Show the yellow button for mobs imported from ItemTree.", "Zeigt den gelben Button für aus ItemTree importierte Mobs.", "Muestra el botón amarillo para las criaturas importadas desde ItemTree.", "Affiche le bouton jaune des créatures importées depuis ItemTree.", "ItemTree’den içe aktarılan yaratıklar için sarı düğmeyi gösterir.", "显示用于从 ItemTree 导入的怪物的黄色按钮。"},
    masterOrientationTip = {"Arrange the targeting buttons in a row or a column.", "Ordnet die Zielbuttons in einer Zeile oder Spalte an.", "Coloca los botones de objetivo en una fila o columna.", "Aligne les boutons de ciblage en ligne ou en colonne.", "Hedefleme düğmelerini yatay veya dikey dizer.", "将目标按钮排列为一行或一列。"},
    buttonSizeTip = {"Scale all buttons on the targeting bar together.", "Skaliert alle Buttons der Zielleiste gemeinsam.", "Ajusta la escala de todos los botones de la barra.", "Ajuste la taille de tous les boutons de la barre.", "Hedef çubuğundaki tüm düğmeleri birlikte ölçekler.", "同步调整目标栏上所有按钮的缩放。"},
    masterSpacingTip = {"Set the gap between buttons on the targeting bar.", "Legt den Abstand zwischen den Buttons der Zielleiste fest.", "Define la distancia entre los botones de la barra.", "Règle l’écart entre les boutons de la barre.", "Hedef çubuğundaki düğmeler arasındaki boşluğu ayarlar.", "设置目标栏中按钮之间的间距。"},
    masterBackgroundTip = {"Show a dark WoW background behind the targeting bar.", "Zeigt einen dunklen WoW-Hintergrund hinter der Zielleiste.", "Muestra un fondo oscuro de WoW detrás de la barra de objetivos.", "Affiche un fond sombre de WoW derrière la barre de ciblage.", "Hedef çubuğunun arkasında koyu WoW arka planı gösterir.", "在目标栏后显示魔兽世界的深色背景。"},
    masterBorderTip = {"Draw a bronze frame around the entire targeting bar.", "Zeigt einen Bronzerahmen um die gesamte Zielleiste.", "Muestra un borde de bronce alrededor de toda la barra.", "Affiche un cadre bronze autour de toute la barre.", "Hedef çubuğunun tamamına bronz çerçeve ekler.", "在整个目标栏周围显示青铜边框。"},
    masterDividersTip = {"Show separators between buttons on the targeting bar.", "Zeigt Trennlinien zwischen den Buttons der Zielleiste.", "Muestra separadores entre los botones de la barra.", "Affiche des séparateurs entre les boutons de la barre.", "Hedef çubuğundaki düğmeler arasında ayırıcı gösterir.", "在目标栏的按钮之间显示分隔线。"},
    showTooltipsTip = {"Show targeting hints when you hover over Next buttons.", "Zeigt Hinweise an, wenn du den Mauszeiger über Zielbuttons bewegst.", "Muestra consejos al pasar el cursor sobre los botones de objetivo.", "Affiche des conseils au survol des boutons de ciblage.", "Hedefleme düğmelerinin üzerine gelince ipucu gösterir.", "将鼠标悬停在目标按钮上时显示提示。"},
    questieTrackerTip = {"Add a Next button beside eligible quests in the Questie tracker.", "Zeigt neben geeigneten Quests im Questie-Tracker einen Zielbutton.", "Añade un botón junto a las misiones compatibles del rastreador de Questie.", "Ajoute un bouton près des quêtes compatibles dans le suivi Questie.", "Questie takibindeki uygun görevlerin yanına hedefleme düğmesi ekler.", "在 Questie 追踪器的适用任务旁添加目标按钮。"},
    trackerSpacingTip = {"Adjust the horizontal offset between the tracker and its targeting buttons.", "Verschiebt die Zielbuttons horizontal relativ zum Tracker.", "Ajusta la distancia horizontal entre el rastreador y sus botones.", "Ajuste le décalage horizontal des boutons par rapport au suivi.", "Takip paneli ile hedefleme düğmeleri arasındaki yatay konumu ayarlar.", "调整目标按钮相对于追踪器的水平偏移。"},
    itemTreeBindingTip = {"Search for mobs imported from ItemTree sources.", "Sucht Mobs, die aus der Quellenliste in ItemTree übernommen wurden.", "Busca criaturas importadas de las fuentes de ItemTree.", "Recherche les créatures importées depuis les sources d’ItemTree.", "ItemTree kaynaklarından içe aktarılan yaratıkları arar.", "搜索从 ItemTree 来源列表导入的怪物。"},
    rareScannerBindingTip = {"Searches marked or focused rares. Enable zone search to include all known rares in your current zone.", "Sucht markierte oder fokussierte Rares. Aktiviere die Gebietssuche für alle bekannten Rares im aktuellen Gebiet.", "Busca raros marcados o enfocados. Activa la búsqueda de zona para incluir todos los raros conocidos de tu zona.", "Recherche les rares marqués ou focalisés. Activez la recherche de zone pour inclure tous les rares connus de la zone actuelle.", "İşaretli veya odaklanılmış nadirleri arar. Bölgedeki tüm bilinen nadirler için bölge aramasını aç.", "搜索已标记或已聚焦的稀有怪。启用区域搜索可搜索当前区域所有已知稀有怪。"},
